# Presentation metadata only: no input values or validation rules are changed.
for(id in names(field_guidance)) {
  h<-field_guidance[[id]]
  h$requirement<-if(grepl('^Required$',h$kind))'Required' else if(grepl('Required|needed',h$kind))'Conditional' else 'Optional'
  h$condition<-h$kind;h$unit<-'Text / choice';h$example<-'Use the value in your source record.'
  field_guidance[[id]]<-h
}
help_detail<-function(ids,requirement,unit,example,condition='',text=NULL)for(id in ids) {
  h<-field_guidance[[id]]%||%list(kind=requirement,text='')
  h$requirement<-requirement;h$unit<-unit;h$example<-example
  h$condition<-if(nzchar(condition))condition else requirement
  if(!is.null(text))h$text<-text
  field_guidance[[id]]<<-h
}
