field_help_control<-function(id,label=NULL) {
  h<-field_guidance[[id]];if(is.null(h))stop('Missing input guidance: ',id)
  title<-if(is.character(label) && length(label)==1L && nzchar(label))label else gsub('_',' ',id)
  shiny::tagList(shiny::span(class=paste('field-requirement',tolower(gsub(' ','-',h$requirement))),h$requirement),
    shiny::tags$button(type='button',class='field-help-trigger','data-field-help'=paste0(id,'-help'),
      'aria-label'=paste('Help for',title),'aria-describedby'=paste0(id,'-help'),'aria-expanded'='false','?'),
    shiny::div(id=paste0(id,'-help'),class='field-help-content',hidden=NA,
      shiny::strong(title),shiny::p(class='help-condition',h$condition),
      shiny::tags$dl(shiny::tags$dt('Meaning'),shiny::tags$dd(h$text),shiny::tags$dt('Unit'),shiny::tags$dd(h$unit),
        shiny::tags$dt('Example'),shiny::tags$dd(h$example))))
}
